    "genre": {
      "lofi_plain": "Relaxed, slightly worn beats for studying or unwinding, like a rainy afternoon in a cafe.",
      "mothership_calm": "Mothership calm",
      "mothership_calm_about": "The ship's own music: slow, spacious, pads and a wordless choir, bells, a steel pan and soft deep drums.",
      "mothership_calm_plain": "The ship's own quiet music: slow and spacious, for relaxing, reading or drifting off.",
      "synthwave": "Synthwave",
      "synthwave_about": "Eighties-style synths at 80 to 118: a snare in a big room cut short, a bass of steady sixteenths, chords played as rising arpeggios, a gliding lead, and long reverbs and echoes.",
      "synthwave_plain": "Retro 1980s synthesizer music, like a night drive through a neon city.",
      "electro_swing_plain": "Old 1930s jazz meets modern dance beats: bouncy, cheerful music to tap your feet to.",
      "house": "House",
      "house_about": "Four on the floor at 120 to 126, a clap on two and four and an open hi-hat on every off-beat, a bass and short chord stabs that pump under the kick, fills down the toms, and a breakdown and build before the drop.",
      "house_plain": "Steady dance music with a kick drum on every beat, made for moving.",
      "lofi": "Lo-fi",
      "lofi_about": "Relaxed and a little worn: swung beats, an electric piano, a round bass, tape wobble and vinyl crackle.",
      "deep_dubstep_plain": "Slow, heavy beats with a deep bass you feel more than hear, dark and spacious.",
      "drum_and_bass": "Drum and bass",
      "drum_and_bass_about": "Fast breakbeat-style drums at 170 to 176 with a ride on every eighth, a deep rolling bass from two detuned saws over a clean sub, soft pads, and a build that ends in a tape stop before the drop.",
      "drum_and_bass_plain": "Very fast, rolling drums over a deep bass: high-energy music for running or racing.",
      "electro_swing": "Electro swing",
      "electro_swing_about": "Swing-era jazz over house beats at 128 beats a minute: swung rhythm, a walking upright bass, a steel-string guitar strumming, brass stabs, and a lead (clarinet, violin, saxophone, vibraphone or piano) calling with another voice answering. Each piece has its own key, chords and riffs.",
      "ambient": "Ambient",
      "ambient_about": "No drums and no beat: slowly changing pads over a low drone, a few bell or harp notes far apart echoing in time, and a long, soft hall.",
      "ambient_plain": "No beat at all: slow, floating sound for focus, sleep or quiet thinking.",
      "deep_dubstep": "Deep dubstep",
      "deep_dubstep_about": "Half-time beats at 140 with the snare on three, a deep, round sub that dips under each kick, a bass that wobbles in time and growls in vowels, and builds that fall silent before the drop."
    },
